    for key in ('Geometry', 'Remaining', 'Status'): end.repeat_items.new('GEOMETRY', key)
    for key in ('Valid', 'Any Union'): end.repeat_items.new('BOOLEAN', key)
    begin.pair_with_output(end)
    g.set(inp.outputs['Pavement'], begin.inputs['Geometry']); begin.inputs['Valid'].default_value = True
    g.set(g.switch(within, 0, count, 'INT'), begin.inputs['Iterations'])
    at = begin.outputs['Iteration']
    def read(key): return g.sample(rows, g.named('st_sb_'+key), at)
